CREATE TABLE IF NOT EXISTS game_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, cycle_number INTEGER NOT NULL, contact_ticket TEXT NOT NULL, email TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'ja', assigned_q_json TEXT NOT NULL, current_index INTEGER NOT NULL DEFAULT 0, correct_count INTEGER NOT NULL DEFAULT 0, phase TEXT NOT NULL DEFAULT 'quiz', quiz_passed INTEGER, started_at TEXT NOT NULL, quiz_done_at TEXT, vote_done_at TEXT, UNIQUE (cycle_number, contact_ticket));
